import sys, os, json, math
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from lib import *
AD = "/_plugins/_anomaly_detection"
SRC = "compat-ad-src"
T0 = 1700000000000
nd = "".join(json.dumps(x) + "\n" for i in range(120) for x in ({"index": {"_id": str(i)}}, {"ts": T0 + i * 60000, "v": round(10 + math.sin(i / 5) + (20 if i in (90, 91) else 0), 4), "host": "h" + str(i % 2), "city": "c" + str(i % 3)}))
def det(name="d1", **kw):
    d = {"name": name, "description": "x", "time_field": "ts", "indices": [SRC],
         "feature_attributes": [{"feature_name": "f", "feature_enabled": True, "aggregation_query": {"f": {"avg": {"field": "v"}}}}],
         "filter_query": {"match_all": {}}, "detection_interval": {"period": {"interval": 1, "unit": "Minutes"}}, "window_delay": {"period": {"interval": 1, "unit": "Minutes"}}}
    d.update(kw); return d
steps = [
 step("create detector", "POST", AD + "/detectors", det("compat-d1"), capture={"d": "/_id"}),
 step("get detector", "GET", AD + "/detectors/{d}"),
 step("get detector with job", "GET", AD + "/detectors/{d}", query={"job": "true"}),
 step("get detector task", "GET", AD + "/detectors/{d}", query={"task": "true"}),
 step("get detector head", "HEAD", AD + "/detectors/{d}"),
 step("get missing detector", "GET", AD + "/detectors/nope"),
 step("create duplicate name", "POST", AD + "/detectors", det("compat-d1")),
 step("update detector", "PUT", AD + "/detectors/{d}", det("compat-d1", description="changed")),
 step("update with seq_no", "PUT", AD + "/detectors/{d}", det("compat-d1", description="changed 2"), {"if_seq_no": "0", "if_primary_term": "1"}),
 step("update missing", "PUT", AD + "/detectors/nope", det("compat-d1")),
 step("create without time_field", "POST", AD + "/detectors", {k: v for k, v in det("compat-bad1").items() if k != "time_field"}),
 step("create without features", "POST", AD + "/detectors", det("compat-bad2", feature_attributes=[]), capture={"bad2": "/_id"}),
 step("create with feature of unknown field", "POST", AD + "/detectors", det("compat-bad3", feature_attributes=[{"feature_name": "f", "feature_enabled": True, "aggregation_query": {"f": {"avg": {"field": "nope"}}}}])),
 step("create with bad aggregation", "POST", AD + "/detectors", det("compat-bad4", feature_attributes=[{"feature_name": "f", "feature_enabled": True, "aggregation_query": {"f": {"nope": {"field": "v"}}}}])),
 step("create with two aggregations in a feature", "POST", AD + "/detectors", det("compat-bad5", feature_attributes=[{"feature_name": "f", "feature_enabled": True, "aggregation_query": {"f": {"avg": {"field": "v"}}, "g": {"max": {"field": "v"}}}}]), capture={"bad5": "/_id"}),
 step("create with duplicate feature names", "POST", AD + "/detectors", det("compat-bad6", feature_attributes=[{"feature_name": "f", "feature_enabled": True, "aggregation_query": {"f": {"avg": {"field": "v"}}}}, {"feature_name": "f", "feature_enabled": True, "aggregation_query": {"g": {"max": {"field": "v"}}}}])),
 step("create with unknown index", "POST", AD + "/detectors", det("compat-bad7", indices=["compat-ad-nope"])),
 step("create with bad interval", "POST", AD + "/detectors", det("compat-bad8", detection_interval={"period": {"interval": 0, "unit": "Minutes"}})),
 step("create with bad unit", "POST", AD + "/detectors", det("compat-bad9", detection_interval={"period": {"interval": 1, "unit": "Fortnights"}})),
 step("create with negative window_delay", "POST", AD + "/detectors", det("compat-bad10", window_delay={"period": {"interval": -1, "unit": "Minutes"}})),
 step("create with shingle_size zero", "POST", AD + "/detectors", det("compat-bad11", shingle_size=0)),
 step("create with shingle_size 60", "POST", AD + "/detectors", det("compat-bad12", shingle_size=60), capture={"bad12": "/_id"}),
 step("create with name too long", "POST", AD + "/detectors", det("n" * 100)),
 step("create with bad name characters", "POST", AD + "/detectors", det("bad name!")),
 step("create with unknown key", "POST", AD + "/detectors", det("compat-bad13", nope=1), capture={"bad13": "/_id"}),
 step("create high cardinality", "POST", AD + "/detectors", det("compat-hc", category_field=["host"]), capture={"hc": "/_id"}),
 step("get high cardinality", "GET", AD + "/detectors/{hc}"),
 step("create with category field of unknown type", "POST", AD + "/detectors", det("compat-bad14", category_field=["v"])),
 step("create with two category fields", "POST", AD + "/detectors", det("compat-hc2", category_field=["host", "city"]), capture={"hc2": "/_id"}),
 step("create with three category fields", "POST", AD + "/detectors", det("compat-bad15", category_field=["host", "city", "city"])),
 step("create with result index", "POST", AD + "/detectors", det("compat-ri", result_index="opensearch-ad-plugin-result-compat"), capture={"ri": "/_id"}),
 step("create with bad result index", "POST", AD + "/detectors", det("compat-bad16", result_index="nope-index")),
 step("validate detector", "POST", AD + "/detectors/_validate", det("compat-v1")),
 step("validate detector with problems", "POST", AD + "/detectors/_validate", {"name": "compat-v2"}),
 step("validate unknown type", "POST", AD + "/detectors/_validate/nope", det("compat-v1")),
 step("validate duplicate name", "POST", AD + "/detectors/_validate", det("compat-d1")),
 step("preview detector", "POST", AD + "/detectors/_preview", {"period_start": T0 + 40 * 60000, "period_end": T0 + 115 * 60000, "detector": det("compat-p1")}),
 step("preview by id", "POST", AD + "/detectors/{d}/_preview", {"period_start": T0 + 40 * 60000, "period_end": T0 + 115 * 60000}),
 step("preview with too short a period", "POST", AD + "/detectors/_preview", {"period_start": T0, "period_end": T0 + 60000, "detector": det("compat-p2")}),
 step("preview with start after end", "POST", AD + "/detectors/_preview", {"period_start": T0 + 115 * 60000, "period_end": T0, "detector": det("compat-p3")}),
 step("preview without detector", "POST", AD + "/detectors/_preview", {"period_start": T0, "period_end": T0 + 60000 * 60}),
 step("search detectors", "POST", AD + "/detectors/_search", {"query": {"match_all": {}}, "sort": [{"name.keyword": "asc"}]}),
 step("search detectors by name", "POST", AD + "/detectors/_search", {"query": {"term": {"name.keyword": "compat-d1"}}}),
 step("search detectors GET", "GET", AD + "/detectors/_search", {"query": {"match_all": {}}, "size": 0}),
 step("detector count", "GET", AD + "/detectors/count"),
 step("detector match", "GET", AD + "/detectors/compat-d1/_match"),
 step("detector match missing", "GET", AD + "/detectors/compat-nope/_match"),
 step("stats", "GET", AD + "/stats"),
 step("stats by name", "GET", AD + "/stats/anomaly_detectors_index_status,detector_count"),
 step("stats of a node", "GET", AD + "/_local/stats"),
 step("stats unknown name", "GET", AD + "/stats/nope"),
 step("profile stopped", "GET", AD + "/detectors/{d}/_profile"),
 step("profile of one type", "GET", AD + "/detectors/{d}/_profile/state"),
 step("profile with unknown type", "GET", AD + "/detectors/{d}/_profile/nope"),
 step("profile all", "GET", AD + "/detectors/{d}/_profile", query={"_all": "true"}),
 step("profile missing", "GET", AD + "/detectors/nope/_profile"),
 step("start detector", "POST", AD + "/detectors/{d}/_start"),
 step("start again", "POST", AD + "/detectors/{d}/_start"),
 step("start missing", "POST", AD + "/detectors/nope/_start"),
 step("profile started", "GET", AD + "/detectors/{d}/_profile", poll=("/state", "INIT", 30)),
 step("get detector with job after start", "GET", AD + "/detectors/{d}", query={"job": "true"}),
 step("update running detector", "PUT", AD + "/detectors/{d}", det("compat-d1", description="while running")),
 step("delete running detector", "DELETE", AD + "/detectors/{d}"),
 step("stop detector", "POST", AD + "/detectors/{d}/_stop"),
 step("stop again", "POST", AD + "/detectors/{d}/_stop"),
 step("stop missing", "POST", AD + "/detectors/nope/_stop"),
 step("profile stopped again", "GET", AD + "/detectors/{d}/_profile"),
 step("start historical analysis", "POST", AD + "/detectors/{d}/_start", {"start_time": T0, "end_time": T0 + 100 * 60000}, capture={"task": "/_id"}),
 step("get detector task after historical start", "GET", AD + "/detectors/{d}", query={"task": "true"}, poll=("/anomaly_detector_task/state", "FINISHED", 60)),
 step("historical task profile", "GET", AD + "/detectors/{d}/_profile", query={"_all": "true"}),
 step("search tasks", "POST", AD + "/detectors/tasks/_search", {"size": 0, "query": {"match_all": {}}}),
 step("stop historical", "POST", AD + "/detectors/{d}/_stop", query={"historical": "true"}),
 step("results search", "POST", AD + "/detectors/results/_search", {"size": 0, "query": {"match_all": {}}}),
 step("top anomalies", "POST", AD + "/detectors/{hc}/results/_topAnomalies/true", {"size": 3, "category_field": ["host"], "start_time_ms": T0, "end_time_ms": T0 + 120 * 60000}),
 step("delete result index detector", "DELETE", AD + "/detectors/{ri}"),
 step("delete hc2", "DELETE", AD + "/detectors/{hc2}"),
 step("delete bad2", "DELETE", AD + "/detectors/{bad2}"),
 step("delete bad5", "DELETE", AD + "/detectors/{bad5}"),
 step("delete bad12", "DELETE", AD + "/detectors/{bad12}"),
 step("delete bad13", "DELETE", AD + "/detectors/{bad13}"),
 step("delete hc", "DELETE", AD + "/detectors/{hc}"),
 step("delete detector", "DELETE", AD + "/detectors/{d}"),
 step("delete again", "DELETE", AD + "/detectors/{d}"),
 step("get deleted", "GET", AD + "/detectors/{d}"),
 step("legacy route", "GET", "/_opendistro/_anomaly_detection/stats/detector_count"),
 step("settings", "GET", "/_cluster/settings", query={"include_defaults": "true", "filter_path": "defaults.plugins.anomaly_detection.*"}),
]
VOL = ["took", "_seq_no", "_primary_term", "last_update_time", "feature_id", "enabled_time", "disabled_time", "last_update_time", "execution_start_time", "execution_end_time", "task_progress", "init_progress", "estimated_minutes_left", "started_by", "user", "coordinating_node", "worker_node", "task_id", "model_id", "node_id", "detector_task_id", "_score", "last_updated_time", "id", "start_time", "end_time", "ad_models_memory_usage", "ad_executing_batch_task_count", "ad_total_batch_task_execution_count", "ad_canceled_batch_task_count", "ad_batch_task_failure_count", "model_size_in_bytes", "profile_time", "value", "ad_execute_request_count", "ad_execute_failure_count", "ad_hc_execute_request_count", "ad_hc_execute_failure_count"]
cl = [("DELETE", "/" + SRC, None, {"ignore_unavailable": "true"})] + [("POST", "/" + i + "/_delete_by_query", {"query": {"match_all": {}}}, {"refresh": "true", "ignore_unavailable": "true"}) for i in (".opendistro-anomaly-detectors", ".opendistro-anomaly-detector-jobs", ".opendistro-anomaly-detection-state", ".opendistro-anomaly-checkpoints", ".opendistro-anomaly-results*")]
run(sys.argv[1:], "anomaly detection routes", "The stock Anomaly Detection plugin's detector, validate, preview, start, stop, profile, search, stats and results routes: single entity, high cardinality and historical analysis. Generated ids are placeholders.",
    steps, volatile=VOL, cleanup=cl,
    setup=[("PUT", "/" + SRC, {"settings": {"number_of_shards": 1, "number_of_replicas": 0}, "mappings": {"properties": {"ts": {"type": "date"}, "v": {"type": "double"}, "host": {"type": "keyword"}, "city": {"type": "keyword"}}}}),
           ("POST", "/" + SRC + "/_bulk", None, {"refresh": "true"}, nd)],
    setup_note=f"index {SRC}: 120 documents one a minute from epoch ms {T0}, v a sine around 10 with a spike of 20 at minutes 90 and 91, keyword host (2 values) and city (3 values)")
